function renderBattleHud(force=false){const parts=battleJudgment.split(' '),grade=parts[0]==='判定—'?'—':parts[0],time=parts.find(v=>/\d.*s$/.test(v))||'—s';for(const [i,[id,value]] of [['hudGrade','判定 '+grade],['hudTime','タイム '+time],['hudKills','撃破 '+killed+' / '+STAGES[stage].count]].entries()){const el=document.getElementById(id);if(!el||(!force&&el.textContent===value))continue;el.textContent=value;el.getAnimations().forEach(a=>a.cancel());if(!$('#reduceMotion').checked)el.animate([{opacity:0,transform:'translateX(60px) skewX(-18deg)',clipPath:'inset(0 0 0 100%)'},{opacity:1,transform:'translateX(-5px) skewX(-8deg)',clipPath:'inset(0)'},{opacity:1,transform:'translateX(0) skewX(0)',clipPath:'inset(0)'}],{duration:240,delay:i*75,fill:'backwards',easing:'cubic-bezier(.15,.75,.3,1)'});}}
