function updateTitleDemo(){const el=$('.title-demo');if(!el)return;el.style.background='none';let cv=el.querySelector('canvas');if(!cv){cv=document.createElement('canvas');cv.width=360*pixelRatio;cv.height=240*pixelRatio;el.append(cv);}const t=idle%3,row=t<1?2:t<1.6?3:0,frame=clamp(t<1?Math.floor(t*4):t<1.6?Math.floor((t-1)/.6*4):Math.floor(t*4)%4,0,3),g=cv.getContext('2d');g.setTransform(pixelRatio,0,0,pixelRatio,0,0);g.imageSmoothingQuality='high';g.clearRect(0,0,360,240);el.dataset.pose=t<1?'charge':t<1.6?'slash':'idle';el.style.setProperty('--guide','0');const f=frameLookup.get(`rena:${row}:${frame}`);g.save();g.beginPath();g.rect(0,0,350,240);g.clip();if(f)individualSprite(f,130,225,180,g);else{const meta=window.SWEEPER_SPRITES?.renaMoves,im=imgs.renaMoves;if(meta&&im?.complete&&im.naturalWidth){const c=meta.cells[row][frame],scale=180/meta.referenceHeight,[sx,sy,sw,sh]=c.rect;g.drawImage(im,sx,sy,sw,sh,130+(sx-c.anchorX)*scale,225+(sy-c.anchorY)*scale,sw*scale,sh*scale);}}g.restore();if(t<1){g.strokeStyle='#9affb8';g.lineWidth=3;g.beginPath();const foot=130+V.frontFootOffset*180/V.playerSize;g.moveTo(foot,222);g.lineTo(foot+P.reach*180/V.playerSize*(1-t),222);g.stroke();}}

function beginStage(n){resetTransient();stage=n;END=n===3?V.bossWidth:V.width;screen='battle';player=n===3?V.bossPlayerStart:V.playerStart;enemies=[];spawned=0;killed=0;worldTime=0;nextSpawn=0;stageGold=0;chargeNoticeTTL=0;battleJudgment='判定— —s';voiceTTL=0;if(n===0)fever=0;cooldown=T.phaseStartDelay;pose=0;particles=[];hide();playMusic(audio['phase'+(n+1)]?'phase'+(n+1):n===3?'boss':'stage');if(n===3){addEnemy();intro={elapsed:0,from:clamp(enemies[0].x-W/2,0,END-W),to:clamp(player-W/2,0,END-W)};}message('Phase '+(n+1)+' / '+STAGES[n].name,'敵を倒し、防衛装置を守れ。',n===3?'巨大な拳の予備動作を見極めよう。':'ポータルから敵が出現する。');renderBattleMessages();updateHud();}
function eSize(e){return TYPES[e.type].size;}
