function addEnemy(){const st=STAGES[stage],type=st.types[spawned%st.types.length],def=TYPES[type],hp=def.hp*st.hp;enemies.push({type,x:stage===3?V.bossStart:END+V.enemyEntryMargin+(spawned%3)*V.spawnSpread,y:targetY({type}),vy:0,grounded:true,hp,max:hp,t:0,contact:0,hit:0,dash:3.2+spawned%3,baseTimer:null,bossWait:C.boss.initialWait,attack:null,attackCycle:0,normalWait:0,depth:spawned%3,pattern:0});spawned++;}
function startAttack(){
 if(paused||settings.open)return;
 if(screen==='finale'){guardPress();return;}
 if(screen!=='battle')return;
 if(attackLocked()){cooldown=Math.max(cooldown,T.rearm);return;}
 if(charge!==null)return;charge=0;chargeStart=performance.now();window.TimingProbe?.mark('chargeStart',{time:chargeStart});pose=2;chargeSound=se('charge');
}
