function playerBody(){return {left:player-P.bodyHalfWidth,right:player+P.bodyHalfWidth,top:FLOOR+knockbackY-P.bodyHeight,bottom:FLOOR+knockbackY};}
function enemyBody(e){const d=TYPES[e.type];return {left:e.x-d.bodyHalfWidth,right:e.x+d.bodyHalfWidth,top:e.y-d.bodyHeight,bottom:e.y};}
