function updateReaction(dt){const r=reaction;r.elapsed+=dt;if(r.feverAttack&&r.elapsed>=F.windup){pose=6;if(!r.cutinShown){r.cutinShown=true;showCutin('musou');se('feverRelease');}}if(!r.applied&&r.elapsed>=r.applyAt){r.applied=true;r.apply();if(screen==='finale')return;}
 if(r.kind==='miss'&&r.applied){const t=clamp((r.elapsed-r.applyAt)/T.flightDuration,0,1);player=r.from+(r.to-r.from)*(1-(1-t)*(1-t));knockbackY=-r.height*4*t*(1-t);}
 if(r.elapsed>=r.duration){if(r.kind==='miss'){player=r.to;contactGrace=T.contactGrace;}knockbackY=0;reaction=null;pose=0;cooldown=Math.max(cooldown,T.rearm);needsRelease=inputsHeld();if(stageClearPending){stageClearPending=false;stage===3?startFinale():beginVictory();}}
}
function cleanDead(){const dead=enemies.filter(e=>e.hp<=0);for(const e of dead){if(e.type===3)defeatedBoss={x:e.x,y:e.y};gold+=TYPES[e.type].gold;stageGold+=TYPES[e.type].gold;killed++;}enemies=enemies.filter(e=>e.hp>0);if(killed>=STAGES[stage].count){if(stage===3){reaction=null;knockbackY=0;stageClearPending=false;startFinale();}else stageClearPending=true;}}
