function lose(){resetTransient();screen='defeat';gold=0;pose=8;playMusic('gameover');show('<div class="eyebrow">DEFENCE SYSTEM / OFFLINE</div><img class="scene-art" src="assets/images/bg-gameover.png" alt="街を守れず落ち込むレナ"><h2>街の灯りが、消える。</h2><p class="muted">所持Gは没収。強化は保持します。<br>Phase 1から、もう一度。</p><div class="actions"><button id="retry" class="primary">再挑戦 →</button><button id="back">タイトルへ</button></div>');message('防衛装置が破壊された。','強化レベルは引き継ぎます。','次は、街を守り抜こう。');$('#retry').onclick=()=>{se('revive');retry++;beginStage(0);};$('#back').onclick=()=>{se('confirm');title();};}
