function finaleMessages(phase){const order=directorConfig.flow.indexOf(phase),at=p=>order>=directorConfig.flow.indexOf(p);let voice=TALK.clear[3],system='周辺エリアの安全が確保された';if(at('fallHold'))voice='ん？ 一体何だ。子ども！？';if(at('pouchHold'))system='新たな生命体の存在を確認';if(at('precharge'))system='高密度の波動検知、出力最大';if(at('rotate'))voice='電撃剣の力をBPM・シールドに。高橋名人のように連打しろ！';if(at('waiting'))system='最初の押下から、1秒間連打！';if(at('safe')){voice='あのレーザーを跳ね返したぞ。徹夜で作っといた甲斐があったぜ';system='損傷ゼロ、ボーナス加算×'+guardCount;}if(at('celebrate')){voice='ありがとうレナ、最高の気分だぜ。今夜は皆でパァッと祝杯だ';system='オールクリア、貴方に賛辞を';}message(battleJudgment+' 撃破'+killed+'/'+STAGES[stage].count,voice,system);}
function setFinalePhase(phase){finale.phase=phase;finale.elapsed=0;$('#warningBanner').classList.remove('count-flash','count-pop');$('#alertSweep').hidden=phase!=='alert';$('#warningBanner').hidden=!['label','waiting','counting','pop'].includes(phase);if(phase==='alert')se('alert');if(phase==='rotate')se('guardMode');if(phase==='label')se('guardBlock');if(phase==='safe')se('guardPerfect');if(phase==='celebrate')se('clear');if(phase==='pop'){if(music)music.pause();musicPlaying=false;musicResume=false;se('stop');$('#warningBanner').style.setProperty('--flash-duration',phaseDuration('pop')+'s');$('#warningBanner').classList.add('count-flash');guardCount=Math.max(1,finale.count);}finaleMessages(phase);renderGuardDigits(finale.count);}
