 clock+=dt;idle+=dt;if(!paused&&!settings.open&&cutin){cutin.elapsed+=dt;if(cutin.elapsed>=cutinHold()+C.effects.fade)cutin=null;renderCutin();}updateTitleDemo();if(readTimer>0){readTimer-=dt;if(readTimer<=0)$('#readout').textContent='';}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').textContent='';}
